#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.AI;
namespace DeliveryService.Mok.Editor {
public static class SlumCombatTest {
const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);
static void Check(bool b,string s,Action<string> log){if(!b)throw new Exception(s);log("PASS: "+s);}
public static IEnumerator RunCore(Action<string> log){
var cycle=UnityEngine.Object.FindFirstObjectByType<DayNightCycle>();cycle.enabled=false;cycle.isShopOpen=true;cycle.currentTime=10;var robbery=UnityEngine.Object.FindFirstObjectByType<RobberyManager>();robbery.enabled=false;foreach(var car in UnityEngine.Object.FindObjectsByType<CarMov>(FindObjectsSortMode.None))car.enabled=false;
var player=UnityEngine.Object.FindFirstObjectByType<PlayerCombat>();player.GetComponent<PlayerMove>().enabled=false;player.GetComponent<CharacterController>().enabled=false;foreach(var look in player.GetComponentsInChildren<CameraMove>())look.enabled=false;var inv=player.GetComponent<ToppingInventory>();inv.RemoveItem();inv.RemovePizza();inv.ClearPackagedPizzas();Cursor.lockState=CursorLockMode.Locked;NavMesh.SamplePosition(new Vector3(-265,0,-5),out var spot,3,NavMesh.AllAreas);player.transform.position=spot.position;
MoneyManager.Instance.currentMoney=50000;var pizza=new PizzaData(new List<string>{"dough","sauce","cheese"},true);inv.AddPackagedDataStack(new List<PizzaData>{pizza});Check(robbery.TrySpawnForTesting(),"빈민촌 강도 소환",log);yield return null;var gang=UnityEngine.Object.FindObjectsByType<SlumRobberCombat>(FindObjectsSortMode.None);Check(gang.Length>=2&&gang.All(g=>!g.GetComponent<RobberAI>().enabled&&g.Combat.IsAggressive&&!g.Combat.CanBePickpocketed),"2~3명 전투 강도·접촉 강탈 정지·소매치기 제외",log);foreach(var g in gang)g.Combat.enabled=false;
var enemy=gang[0];enemy.GetComponent<NavMeshAgent>().Warp(spot.position+Vector3.forward*1.5f);player.View.transform.position=spot.position+Vector3.up*1.25f;player.View.transform.LookAt(enemy.transform.position+Vector3.up*1.2f);Physics.SyncTransforms();Check(player.TryKick(),"포장 피자를 들고 발차기 시작",log);float until=Time.time+1;while(Time.time<until)yield return null;Check(enemy.Combat.Health==70&&enemy.GetComponent<NPCControl>().IsKnockedDown,"실제 발차기 타격·30 피해·레그돌",log);Check(inv.HasPackagedPizzas()&&ReferenceEquals(inv.GetHeldPackagedPizzas()[0],pizza),"공격 중 들고 있는 피자 보존",log);
// 두 번째 강도의 실제 주먹 판정으로 첫 피격을 만든다.
var attacker=gang[1];attacker.GetComponent<NavMeshAgent>().Warp(player.transform.position+Vector3.forward*2);attacker.transform.LookAt(new Vector3(player.transform.position.x,attacker.transform.position.y,player.transform.position.z));Physics.SyncTransforms();attacker.Combat.StartCoroutine((IEnumerator)typeof(CitizenCombat).GetMethod("Punch",F).Invoke(attacker.Combat,null));until=Time.time+1;while(Time.time<until)yield return null;Check(player.HitsTaken==1&&player.IsDown,"빈민촌 강도 주먹 피격·레그돌",log);Check(inv.HasPackagedPizzas()&&MoneyManager.Instance.currentMoney==50000,"1회 피격 시 강탈 없음",log);
var cargo=UnityEngine.Object.FindFirstObjectByType<BikePizzaStorage>();Set(cargo,"storedPizzas",new List<PizzaData>{new PizzaData(pizza)});
for(int hit=2;hit<=3;hit++){while(player.IsDown)yield return null;until=Time.time+1.4f;while(Time.time<until)yield return null;player.ReceivePunch(10,Vector3.forward,true);player.ReceivePunch(10,Vector3.forward,true);Check(player.HitsTaken==hit,"다중 공격 중복 피격 차단 "+hit,log);if(hit==2)Check(inv.HasPackagedPizzas(),"2회 피격까지 피자 보존",log);}
Check(!inv.HasPackagedPizzas()&&MoneyManager.Instance.currentMoney==50000,"세 번째 피격에만 피자 강탈·현금 보존",log);float maxAlpha=0;while(player.IsDown){maxAlpha=Mathf.Max(maxAlpha,player.hospitalFade.Alpha);yield return null;}Check(MoneyManager.Instance.currentMoney==30000,"병원비 2만원 한 번 청구",log);Check(Vector3.Distance(player.transform.position,player.hospital.position)<1&&maxAlpha>.95f&&player.hospitalFade.Alpha<.01f,"암전 후 병원에서 깨어남",log);Check(cargo.StoredCount==1&&player.HitsTaken==0,"주차한 배달통 보존·피격 횟수 초기화",log);
// 피자가 없는 패배에서는 치료비 전에 소지 현금 비율을 계산한다.
MoneyManager.Instance.currentMoney=50000;player.transform.position=spot.position;Set(player,"<HitsTaken>k__BackingField",2);Set(player,"recoveryUntil",0f);player.ReceivePunch(10,Vector3.right,true);int taken=50000-MoneyManager.Instance.currentMoney;Check(taken>=5000&&taken<=10000,"피자 없으면 패배 시 현금 10~20% 손실",log);while(player.IsDown)yield return null;Check(MoneyManager.Instance.currentMoney==50000-taken-20000,"현금 손실과 병원비 별도 적용",log);
// 일반 지역 강도는 기존 도주형을 유지한다.
player.transform.position=new Vector3(-176,0,-5);Cursor.lockState=CursorLockMode.Locked;until=Time.time+1.4f;while(Time.time<until)yield return null;Check(robbery.TrySpawnForTesting(),"일반 지역 강도 소환",log);yield return null;var ordinary=UnityEngine.Object.FindFirstObjectByType<RobberAI>();Check(ordinary!=null&&ordinary.enabled&&ordinary.GetComponent<SlumRobberCombat>()==null,"일반 강도의 기존 강탈·도주 AI 유지",log);
}
}}
#endif
